input.command:
q(){ /workspace/dataset/test6_executable --a "$1" --b "${2-Z}" --c "${3-Z}" >/tmp/o.txt 2>/tmp/e.txt; r=$?; printf 'rc=%d lines=%d ' "$r" "$(wc -l </tmp/o.txt)"; if [ $r -ne 0 ]; then grep -E '^[A-Za-z]*(Error|Exception)' /tmp/e.txt|head -1; else printf 'host=%s\n' "$(sed -n 2p /tmp/o.txt | cut -c1-40)"; fi; }
mk(){ head -c "$1" /dev/zero | tr '\0' 'a'; }
for n in 62 63 64 65; do printf 'label len %d: ' "$n"; q "http://$(mk $n)/p"; done
for n in 62 63 64; do printf 'label len %d + .com: ' "$n"; q "http://$(mk $n).com/p"; done
echo "--- total length (many 60-char labels):"
for k in 3 5 10; do lbl=$(mk 60); h=""; for i in $(seq 1 $k); do h="$h$lbl."; done; h="${h}com"; printf 'total=%d: ' "${#h}"; q "http://$h/p"; done

